fn longest_prefix(a: &[i32], b: &[i32]) -> usize {
    // Iterate over both slices in lockstep, stopping at the first mismatch.
    for (i, (x, y)) in a.iter().zip(b.iter()).enumerate() {
        if x != y {
            return i;
        }
    }
    // If we never saw a mismatch, the common prefix is as long as the shorter slice.
    a.len().min(b.len())
}

